<script lang="ts">
 import {onMount} from 'svelte';import {Spring,prefersReducedMotion} from 'svelte/motion';import {brightnessValue} from '../islandTime';
 let {value,reduced=false,oninput,oncommit}:{value:number;reduced?:boolean;oninput:(value:number)=>void;oncommit:(value:number)=>void}=$props();
 const liquid=new Spring(100,{stiffness:.08,damping:.52,precision:.015});let held=$state(false),level=$state(100),grip:{id:number;original:number}|null=null;
 let surface=$derived.by(()=>{const difference=liquid.target-liquid.current,amplitude=reduced||prefersReducedMotion.current?0:Math.min(7,Math.abs(difference)*.32);const points=Array.from({length:15},(_,i)=>{const y=Math.max(0,Math.min(100,100-liquid.current+Math.sin(i*.8+liquid.current*.13)*amplitude));return `${i/14*100}% ${y}%`;});return 'polygon('+points.join(',')+',100% 100%,0 100%)';});
 $effect(()=>{const v=brightnessValue(value),instant=reduced||prefersReducedMotion.current;void liquid.set(v,{instant});});
 function change(next:number){level=brightnessValue(next);oninput(level);}
 function point(event:PointerEvent){const r=(event.currentTarget as HTMLElement).getBoundingClientRect();change((r.bottom-event.clientY)/r.height*100);}
 function end(event:PointerEvent,cancel=false){if(grip?.id!==event.pointerId)return;const start=grip.original;grip=null;held=false;try{(event.currentTarget as HTMLElement).releasePointerCapture(event.pointerId);}catch{}if(cancel)change(start);oncommit(cancel?start:level);}
 onMount(()=>{void liquid.set(brightnessValue(value),{instant:true});return()=>{void liquid.set(liquid.current,{instant:true});};});
</script>
<div class="slosh-gauge" role="slider" tabindex="0" aria-label="页面亮度" aria-valuemin="40" aria-valuemax="100" aria-valuenow={brightnessValue(value)} aria-valuetext={brightnessValue(value)+'%'} aria-orientation="vertical" data-held={held} onpointerdown={event=>{if(event.button!==0||grip)return;grip={id:event.pointerId,original:value};held=true;event.currentTarget.setPointerCapture(event.pointerId);point(event);}} onpointermove={event=>{if(grip?.id===event.pointerId)point(event);}} onpointerup={event=>end(event)} onpointercancel={event=>end(event,true)} onkeydown={event=>{if(event.key==='Escape'&&grip){event.preventDefault();change(grip.original);grip=null;held=false;oncommit(level);return;}const step=event.shiftKey?10:2,next=event.key==='Home'?40:event.key==='End'?100:['ArrowUp','ArrowRight'].includes(event.key)?value+step:['ArrowDown','ArrowLeft'].includes(event.key)?value-step:event.key==='PageUp'?value+10:event.key==='PageDown'?value-10:undefined;if(next!==undefined){event.preventDefault();change(next);oncommit(level);}}}>
 <div class="gauge-liquid" style:clip-path={surface} aria-hidden="true"></div><div class="gauge-marks" aria-hidden="true">{#each [40,60,80] as mark}<i style:bottom={mark+'%'}></i>{/each}</div><span class="gauge-readout" aria-hidden="true">{brightnessValue(value)}%</span><span class="gauge-marker" style:bottom={brightnessValue(value)+'%'} aria-hidden="true"></span>
</div>
<style>.slosh-gauge{position:relative;isolation:isolate;overflow:hidden;flex:none;width:82px;height:140px;border:2px solid var(--xy-border);border-radius:8px;background:var(--xy-page);color:var(--xy-ink);touch-action:none;cursor:ns-resize;user-select:none}.gauge-liquid{position:absolute;inset:0;background:var(--xy-accent);opacity:.8}.gauge-marks{position:absolute;inset:0;pointer-events:none}.gauge-marks i{position:absolute;right:0;width:13px;height:2px;background:var(--xy-ink);opacity:.45}.gauge-readout{position:absolute;top:50%;left:50%;translate:-50% -50%;font-size:15px;font-weight:600;font-variant-numeric:tabular-nums;padding:3px 6px;background:var(--xy-panel);border-radius:4px;color:var(--xy-ink);pointer-events:none}.gauge-marker{position:absolute;left:7px;right:7px;height:2px;background:var(--xy-ink);opacity:0;pointer-events:none}.slosh-gauge[data-held=true] .gauge-marker{opacity:1}</style>
